def _rad_reduced_motion():
    """True when the system asks for less motion (RADIDE_REDUCED_MOTION=1, or Windows animations off)."""
    import os as _os
    v = _os.environ.get("RADIDE_REDUCED_MOTION", "").strip().lower()
    if v:
        return v in ("1", "true", "yes", "on")
    if _os.name == "nt":
        try:
            import ctypes
            on = ctypes.c_int(1)
            if ctypes.windll.user32.SystemParametersInfoW(0x1042, 0, ctypes.byref(on), 0):  # CLIENTAREAANIMATION
                return not on.value
        except (AttributeError, OSError, ValueError):
            pass
    return False


class _RadQuietIO:
    """Writes of the animations themselves: their Visible changes do not start show / hide animations."""

    def __init__(self, io):
        self._io = io

    def __getattr__(self, name):
        return getattr(self._io, name)

    def set(self, name, prop, v):
        self._io.quiet = getattr(self._io, "quiet", 0) + 1
        try:
            self._io.set(name, prop, v)
        finally:
            self._io.quiet -= 1


class _RadFx:
    """Animations designed in the Animations window: triggers (load, click, hover, timer, show, hide,
    after another animation, manual), chains, reduced motion and Animate() from code."""

    def __init__(self, owner, io, storyboards, triggers, reduced=True, alpha=False, transform=False):
        self._o, self._io, self._qio = owner, io, _RadQuietIO(io)
        self.Storyboards, self._meta = {}, {}
        self.Triggers = list(triggers)
        self.ReducedMotion = bool(reduced) and _rad_reduced_motion()
        self._alpha, self._transform = bool(alpha), bool(transform)
        self._timers, self._pending, self._show, self._hide = {}, {}, {}, {}
        for d in storyboards:
            sb = _Storyboard(owner, self._qio, d["name"], d["tracks"], repeat=d.get("repeat", False),
                             autoreverse=d.get("autoreverse", False), count=d.get("count", 1))
            self._add(d["fx"], sb, d.get("delayMs", 0), d.get("restore", False), d.get("target", ""))
            try:
                setattr(owner, d["name"], sb)           # self._fx_fx1.Begin() works too
            except AttributeError:
                pass
        io.vis_hook = self._visible
        for t in self.Triggers:
            self._arm(t)

    def _add(self, fx, sb, delay, restore, target):
        self.Storyboards[fx] = sb
        self._meta[fx] = {"delay": int(delay or 0), "restore": bool(restore), "target": target or "",
                          "hiding": False}
        sb.Completed.insert(0, lambda: self._done(fx))

    # ------------------------------------------------------------ triggers
    def _arm(self, t):
        fx, on, src = t.get("fx"), t.get("on"), t.get("source") or ""
        bind = getattr(self._io, "bind", None)
        try:
            if on == "click" and bind is not None:
                bind(src, "click", lambda: self.Begin(fx))
            elif on == "hover" and bind is not None:
                bind(src, "enter", lambda: self.Begin(fx))
                leave = t.get("leave", "reverse")
                if leave == "reverse":
                    bind(src, "leave", lambda: self._reverse(fx))
                elif leave == "stop":
                    bind(src, "leave", lambda: self.Stop(fx))
            elif on == "after":
                sb = self.Storyboards.get(t.get("after"))
                if sb is not None:
                    sb.Completed.append(lambda: self.Begin(fx))
            elif on == "show":
                self._show.setdefault(t.get("target") or "", []).append(fx)
            elif on == "hide":
                self._hide.setdefault(t.get("target") or "", []).append(fx)
        except (AttributeError, KeyError):
            pass                                        # a control that is not there (any more)

    def start(self):
        """After <Form>_Load: animations "On load" begin, "On timer" ones start their timers."""
        for t in self.Triggers:
            if t.get("on") == "load":
                self.Begin(t["fx"])
            elif t.get("on") == "timer" and int(t.get("intervalMs") or 0) > 0:
                tok = object()
                self._timers[t["fx"]] = tok
                ms = int(t["intervalMs"])
                self._io.later(ms, lambda fx=t["fx"], ms=ms, tok=tok: self._every(fx, ms, tok))

    def _every(self, fx, ms, tok):
        if self._timers.get(fx) is not tok:
            return
        self.Begin(fx)
        self._io.later(ms, lambda: self._every(fx, ms, tok))

    def _visible(self, name, on):
        """_RadIO.set(name, "Visible", on) hook: True = handled here (the hide plays first)."""
        if getattr(self._io, "quiet", 0):
            return False
        fxs = [fx for fx in (self._show if on else self._hide).get(name, ()) if fx in self.Storyboards]
        if not fxs or bool(self._io.get(name, "Visible")) == bool(on):
            return False
        if on:
            self._qio.set(name, "Visible", True)
            for fx in fxs:
                self.Begin(fx)
        else:
            for fx in fxs:
                self._meta[fx]["hiding"] = True
                self.Begin(fx)
        return True

    def _done(self, fx):
        m = self._meta.get(fx)
        sb = self.Storyboards.get(fx)
        if m is None or sb is None:
            return
        if m["hiding"]:
            m["hiding"] = False
            sb.Stop()                                   # designed values back, then hidden
            self._qio.set(m["target"], "Visible", False)
        elif m["restore"]:
            sb.Stop()                                   # ended where it started: Anchor / Dock take over

    def _reverse(self, fx):
        sb = self.Storyboards.get(fx)
        if sb is None:
            return
        self._pending.pop(fx, None)
        if self.ReducedMotion:
            sb.Stop()
        else:
            sb.Reverse()

    # ------------------------------------------------------------ API
    def _find(self, fx):
        fx = str(fx or "")
        if fx in self.Storyboards:
            return fx
        return next((k for k, sb in self.Storyboards.items() if sb.Name == fx), None)

    def Begin(self, fx):
        fx = self._find(fx)
        if fx is None:
            return False
        sb = self.Storyboards[fx]
        if self.ReducedMotion:
            if not sb.IsPlaying:
                sb._saved = {}
            sb.Finish()
            return True
        if not sb.IsPlaying:
            sb._saved = {}                              # start from the values the control has now
        delay = self._meta[fx]["delay"]
        if delay > 0:
            tok = object()
            self._pending[fx] = tok
            sb.Seek(0)                                  # first frame now (e.g. slid out), then wait

            def go():
                if self._pending.get(fx) is tok:
                    del self._pending[fx]
                    sb.Begin()
            self._io.later(delay, go)
        else:
            sb.Begin()
        return True

    def Stop(self, fx):
        fx = self._find(fx)
        if fx is None:
            return False
        self._timers.pop(fx, None)
        self._pending.pop(fx, None)
        self._meta[fx]["hiding"] = False
        self.Storyboards[fx].Stop()
        return True

    def SetVisible(self, target, visible):
        target = self._name(target)
        if not self._visible(target, bool(visible)):
            self._qio.set(target, "Visible", bool(visible))

    def _name(self, target):
        if target is None or isinstance(target, str):
            return target or ""
        name = getattr(target, "_rad_name", None)
        if name:
            return name
        for k, v in vars(self._o).items():
            if v is target:
                return k
        return ""

    def Animate(self, target, preset, **opts):
        """Play *preset* on *target* now; returns its storyboard (Stop() / Pause() ...)."""
        target = self._name(target)
        dur0, ease0, restores = _RAD_FX_DEFAULTS.get(preset, (500, "out", True))
        dur = opts.pop("durationMs", opts.pop("duration", dur0))
        delay = opts.pop("delayMs", opts.pop("delay", 0))
        ease = opts.pop("easing", opts.pop("ease", ease0))
        rep = int(opts.pop("repeat", 1) or 0)
        rev = bool(opts.pop("autoreverse", False))
        params = {k.rstrip("_"): v for k, v in opts.items()}      # from_="right" -> from
        tracks, _note = _rad_fx_tracks(preset, params, dur, ease, self._alpha or not target, self._transform,
                                       not target)
        if not tracks:
            raise ValueError("unknown animation preset %r" % (preset,))
        fx = "adhoc:%s:%s" % (target, preset)
        old = self.Storyboards.get(fx)
        if old is not None and old.IsPlaying:
            old.Stop()
        sb = _Storyboard(self._o, self._qio, "_fx_adhoc", [(target, p, k) for p, k in tracks],
                         repeat=rep == 0, autoreverse=rev, count=max(1, rep))
        self._add(fx, sb, delay, restores or rev, target)
        self.Begin(fx)
        return sb


class _RadIO:
    """Reads / writes neutral properties of the Tk widgets (visual states, storyboards, bindings)."""
    vis_hook = None         # animations: callable(name, visible) -> True when it handles the change
    quiet = 0               # > 0 while the animations write (no show / hide hooks)
    GEO = {"Left": "x", "Top": "y", "Width": "width", "Height": "height"}
    REL = {"Left": "relx", "Top": "rely", "Width": "relwidth", "Height": "relheight"}

    def __init__(self, owner):
        self.o = owner
        self._anchored = {}     # (name, prop) -> (offset, rel) of Anchor / Dock before a state / storyboard

    def release(self, name, prop=None):
        """A state / storyboard gave the geometry back: Anchor / Dock place the control again."""
        props = [prop] if prop else list(self.GEO)
        new = {}
        for p in props:
            orig = self._anchored.pop((name, p), None)
            if orig is not None:
                new[self.GEO[p]], new[self.REL[p]] = orig
        if not new:
            return
        self.o._places.setdefault(name, {}).update(new)
        try:
            w = self.w(name)
            if w.winfo_manager() == "place":
                w.place_configure(**new)
        except (tk.TclError, AttributeError):
            pass

    def w(self, name):
        return self.o.root if not name else getattr(self.o, name)

    def _var(self, name):
        try:
            return getattr(self.o, name + "_var")
        except AttributeError:
            return None

    def _font(self, w):
        import tkinter.font as tkfont
        return tkfont.Font(root=w, font=w.cget("font")).actual()

    def get(self, name, prop):
        try:
            w = self.w(name)
            if not name:
                return self._get_form(w, prop)
            if prop == "Text":
                if isinstance(w, tk.Text):
                    return w.get("1.0", "end-1c")
                if isinstance(w, (tk.Entry, ttk.Entry)):
                    return w.get()
                return str(w.cget("text"))
            if prop in self.GEO:
                info = w.place_info() or self.o._places.get(name, {})
                v = info.get(self.GEO[prop])
                if v in (None, "") or float(info.get(self.REL[prop]) or 0):   # anchored: the real value
                    w.update_idletasks()
                    return {"Left": w.winfo_x, "Top": w.winfo_y, "Width": w.winfo_width,
                            "Height": w.winfo_height}[prop]()
                return int(float(v))
            if prop == "BackColor":
                return str(w.cget("bg"))
            if prop == "ForeColor":
                return str(w.cget("fg"))
            if prop == "Visible":
                return w.winfo_manager() == "place"
            if prop in ("FontSize", "FontBold", "FontItalic"):
                a = self._font(w)
                return {"FontSize": abs(int(a["size"])), "FontBold": a["weight"] == "bold",
                        "FontItalic": a["slant"] == "italic"}[prop]
            if prop == "Opacity":
                return 1.0
            if prop == "Checked" and isinstance(w, tk.Radiobutton):
                return self.o._radio.get() == name
            if prop in ("Value", "Checked"):
                var = self._var(name)
                return var.get() if var is not None else w.cget("value")
        except (tk.TclError, AttributeError, ValueError, KeyError, TypeError):
            return None
        return None

    def _get_form(self, w, prop):
        if prop == "Text":
            return w.title()
        if prop == "BackColor":
            return str(w.cget("bg"))
        if prop == "Opacity":
            return float(w.attributes("-alpha"))
        if prop in self.GEO:
            size, _, pos = w.geometry().partition("+")
            ww, hh = (int(v) for v in size.split("x"))
            x, _, y = pos.partition("+")
            return {"Width": ww, "Height": hh, "Left": int(x or 0), "Top": int(y or 0)}[prop]
        return None

    def set(self, name, prop, v):
        if v is None:
            return
        if prop == "Visible" and name and not self.quiet and self.vis_hook is not None \
                and self.vis_hook(name, bool(v)):
            return                                  # an "On show" / "On hide" animation takes over
        try:
            w = self.w(name)
            if not name:
                return self._set_form(w, prop, v)
            if prop == "Text":
                if isinstance(w, tk.Text):
                    state = w.cget("state")
                    w.configure(state="normal")
                    w.delete("1.0", "end")
                    w.insert("1.0", str(v))
                    w.configure(state=state)
                elif isinstance(w, (tk.Entry, ttk.Entry)):
                    var = self._var(name)
                    if var is not None:
                        var.set(str(v))
                    else:
                        w.delete(0, "end")
                        w.insert(0, str(v))
                else:
                    w.configure(text=str(v))
            elif prop in self.GEO:
                key, rel = self.GEO[prop], self.REL[prop]
                opts = self.o._places.setdefault(name, {})
                new = {key: int(v)}
                if float(opts.get(rel) or 0):     # Anchor / Dock: the animated value is absolute
                    self._anchored.setdefault((name, prop), (opts.get(key, 0), opts[rel]))
                    opts.pop(rel, None)
                    new[rel] = 0
                opts[key] = int(v)
                if w.winfo_manager() == "place":
                    w.place_configure(**new)
            elif prop == "BackColor":
                w.configure(bg=v)
            elif prop == "ForeColor":
                w.configure(fg=v)
            elif prop == "Visible":
                if v:
                    w.place(**self.o._places.get(name, {}))
                else:
                    w.place_forget()
            elif prop in ("FontSize", "FontBold", "FontItalic"):
                a = self._font(w)
                size = int(v) if prop == "FontSize" else abs(int(a["size"]))
                bold = bool(v) if prop == "FontBold" else a["weight"] == "bold"
                italic = bool(v) if prop == "FontItalic" else a["slant"] == "italic"
                style = " ".join(s for s, on in (("bold", bold), ("italic", italic)) if on)
                w.configure(font=(a["family"], size, style) if style else (a["family"], size))
            elif prop == "Checked" and isinstance(w, tk.Radiobutton):
                if v:
                    self.o._radio.set(name)
                elif self.o._radio.get() == name:
                    self.o._radio.set("")
            elif prop in ("Value", "Checked"):
                var = self._var(name)
                if var is not None:
                    var.set(bool(v) if prop == "Checked" else int(v))
                else:
                    w.configure(value=int(v))
        except (tk.TclError, AttributeError, ValueError, TypeError):
            pass

    def _set_form(self, w, prop, v):
        if prop == "Text":
            w.title(str(v))
        elif prop == "BackColor":
            w.configure(bg=v)
            client = self.o.__dict__.get("_client")
            if client is not None:
                client.configure(bg=v)
        elif prop == "Opacity":
            w.attributes("-alpha", float(v))
        elif prop in ("Width", "Height"):
            ww, hh = self._get_form(w, "Width"), self._get_form(w, "Height")
            w.geometry(f"{int(v) if prop == 'Width' else ww}x{int(v) if prop == 'Height' else hh}")
        elif prop in ("Left", "Top"):
            x, y = self._get_form(w, "Left"), self._get_form(w, "Top")
            w.geometry(f"+{int(v) if prop == 'Left' else x}+{int(v) if prop == 'Top' else y}")

    def set_items(self, name, items):
        w = self.w(name)
        items = [str(i) for i in items]
        if isinstance(w, tk.Listbox):
            w.delete(0, "end")
            if items:
                w.insert("end", *items)
        elif isinstance(w, ttk.Combobox):
            w.configure(values=items)

    def set_rows(self, name, columns, rows):
        w = self.w(name)
        if hasattr(w, "SetColumns"):
            w.SetColumns(list(columns))
            w.Clear()
            for r in rows:
                w.AddRow(*r)

    def rgb(self, name, prop, value):
        c = _rad_rgb_hex(value)
        if c is None and value:
            try:
                c = tuple(x // 256 for x in self.o.root.winfo_rgb(value))
            except tk.TclError:
                return None
        return c

    def later(self, ms, fn):
        self.o.root.after(int(ms), fn)

    def bind(self, name, event, fn):
        """Animation triggers: event "click" / "enter" / "leave" of a control ("" = the form) calls fn()."""
        w = self.w(name)
        if not name:
            client = self.o.__dict__.get("_client")
            w = client if client is not None else w
        seq = {"click": "<Button-1>", "enter": "<Enter>", "leave": "<Leave>"}[event]

        def call(e):
            if not name and e.widget is not w:      # the form itself, not one of its controls
                return
            fn()
        w.bind(seq, call, add="+")

    def parent_bg(self, name):
        """Background colour of the control's container (fades without transparency blend into it)."""
        try:
            m = self.w(name).master
            try:
                return str(m.cget("bg"))
            except tk.TclError:
                return str(ttk.Style().lookup(m.winfo_class(), "background")) or None
        except (tk.TclError, AttributeError):
            return None

    def on_select(self, name, fn):
        w = self.w(name)
        if isinstance(w, tk.Listbox):
            w.bind("<<ListboxSelect>>", lambda _e: w.curselection() and fn(w.curselection()[0]), add="+")
        elif isinstance(w, ttk.Combobox):
            w.bind("<<ComboboxSelected>>", lambda _e: w.current() >= 0 and fn(w.current()), add="+")

    def hook(self, name, vsm, disabled=False):
        w = self.w(name)
        for seq, state, on in (("<Enter>", "MouseOver", True), ("<Leave>", "MouseOver", False),
                               ("<ButtonPress-1>", "Pressed", True), ("<ButtonRelease-1>", "Pressed", False),
                               ("<FocusIn>", "Focused", True), ("<FocusOut>", "Focused", False)):
            w.bind(seq, lambda _e, s=state, o=on: vsm.Flag(name, s, o), add="+")
        if disabled:            # Tk has no "state changed" event: look at the widget's state
            def poll():
                try:
                    off = str(w.cget("state")) == "disabled"
                except tk.TclError:
                    try:
                        off = bool(w.instate(["disabled"]))
                    except (tk.TclError, AttributeError):
                        off = False
                vsm.Flag(name, "Disabled", off)
                self.o.root.after(120, poll)
            poll()


